USE trabajos_grado_uts;
CREATE TABLE IF NOT EXISTS idea(id INT AUTO_INCREMENT PRIMARY KEY,titulo VARCHAR(180) NOT NULL,descripcion TEXT NOT NULL,nivel VARCHAR(30) NOT NULL,modalidad VARCHAR(60) NOT NULL,estado VARCHAR(30) NOT NULL DEFAULT 'PENDIENTE',creado_por INT NOT NULL,creado_en TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(creado_por) REFERENCES usuario(id),INDEX(estado,nivel));
CREATE TABLE IF NOT EXISTS docente(usuario_id INT PRIMARY KEY,tipo VARCHAR(30) NOT NULL,carga_maxima INT NOT NULL DEFAULT 5,FOREIGN KEY(usuario_id) REFERENCES usuario(id));
CREATE TABLE IF NOT EXISTS asignacion(id INT AUTO_INCREMENT PRIMARY KEY,proyecto_id INT NOT NULL,docente_id INT NOT NULL,tipo VARCHAR(30) NOT NULL,estado VARCHAR(30) NOT NULL DEFAULT 'ACTIVA',asignado_en TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(proyecto_id) REFERENCES proyecto(id),FOREIGN KEY(docente_id) REFERENCES docente(usuario_id));
CREATE TABLE IF NOT EXISTS evaluacion(id INT AUTO_INCREMENT PRIMARY KEY,proyecto_id INT NOT NULL,evaluador_id INT NOT NULL,tipo VARCHAR(30) NOT NULL,concepto VARCHAR(40) NOT NULL,observaciones TEXT,creado_en TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(proyecto_id) REFERENCES proyecto(id),FOREIGN KEY(evaluador_id) REFERENCES docente(usuario_id));